function HowItWorks(){const steps=[['01','Bring your footage','Upload a video or import a permitted YouTube link. OpenShorts reads the metadata and source duration.'],['02','Find the moment','A local transcript model (or imported SRT subtitles) powers ranked clip suggestions.'],['03','Make it yours','Review suggested clips, trim the timeline, pick caption style, and adjust placement and colors.'],['04','Export in vertical','Render a polished 1080×1920 MP4 with optional face-focused crop and karaoke captions.']];return <PublicShell eyebrow="THE PROCESS" title={<>From raw footage<br/><span className="gradient-text">to remarkable.</span></>} desc="Four clear steps. Nothing between you and your next great short."><div className="steps-grid">{steps.map(([n,title,desc])=><div className="step-card" key={n}><span>{n}</span><h3>{title}</h3><p>{desc}</p></div>)}</div></PublicShell>}
